import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;
public class LinkCheck {
 static Map<String,ClassNode> all=new HashMap<>();static List<ClassNode> check=new ArrayList<>();
 static void load(String file,boolean selected)throws Exception{try(ZipFile z=new ZipFile(file)){for(ZipEntry e:Collections.list(z.entries()))if(e.getName().endsWith(".class")){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e)).accept(c,0);all.put(c.name,c);if(selected)check.add(c);}}}
 static boolean method(String o,String n,String d,Set<String> seen){if(o==null||!seen.add(o))return false;ClassNode c=all.get(o);if(c==null){try{c=new ClassNode();new ClassReader(o).accept(c,0);all.put(o,c);}catch(Exception ex){return false;}}for(MethodNode m:c.methods)if(m.name.equals(n)&&m.desc.equals(d))return true;for(String i:c.interfaces)if(method(i,n,d,seen))return true;return !n.equals("<init>")&&method(c.superName,n,d,seen);}
 static boolean field(String o,String n,String d,Set<String> seen){if(o==null||!seen.add(o))return false;ClassNode c=all.get(o);if(c==null){try{c=new ClassNode();new ClassReader(o).accept(c,0);all.put(o,c);}catch(Exception ex){return false;}}for(FieldNode f:c.fields)if(f.name.equals(n)&&f.desc.equals(d))return true;for(String i:c.interfaces)if(field(i,n,d,seen))return true;return field(c.superName,n,d,seen);}
 public static void main(String[] a)throws Exception{for(int i=1;i<a.length;i++)load(a[i],false);load(a[0],true);int count=0;for(ClassNode c:check)for(MethodNode m:c.methods){if(m.instructions.size()>0)new Analyzer<BasicValue>(new BasicVerifier()).analyze(c.name,m);for(AbstractInsnNode n:m.instructions.toArray()){if(n instanceof MethodInsnNode){MethodInsnNode j=(MethodInsnNode)n;if(!method(j.owner,j.name,j.desc,new HashSet<>()))throw new AssertionError(c.name+" -> method "+j.owner+"."+j.name+j.desc);count++;}if(n instanceof FieldInsnNode){FieldInsnNode j=(FieldInsnNode)n;if(!field(j.owner,j.name,j.desc,new HashSet<>()))throw new AssertionError(c.name+" -> field "+j.owner+"."+j.name+j.desc);count++;}}}System.out.println("PASS: "+check.size()+" classes; "+count+" method/field references; bytecode verified");}
}
